"""WB_DumpPredictor: detect a tape opponent and predict its premium dumps (Builder A).

Tape agents (herd-safe/W3, v15stack/W0 and the 2945 Farm) replay one of a shared set of
route tapes. The route is fixed at step 144 by the first two unlocked shops (plus a
rival-key override the router reads at step 2), so their premium SELL schedule is a
function of public data. This module:

1. detects the opponent's family from its turn-1 market orders, which are visible in its
   money and in the WHEAT market inventory at obs step 1. The expected values are computed
   exactly: _wb_dp_market is a port of the engine's per-unit lockstep, with our own turn-1
   orders on the other side;
2. maps (family, route) to the dumps that family executes, from a measured table
   (WB_DP_DUMPS, generated by experiments/splice/_probe_dumps.py over real episodes);
3. answers upcoming(obs, product, horizon): the opponent's predicted dumps in the window.

Unknown opponent (top six or anything else): no predictions, so no front-running.

Build notes: concatenated after price_model.py and sell_engine.py, so every top-level name
carries WB_ / _wb_; the import line below is dropped by experiments/splice/build.py.
Stateful per instance (observe() keeps the step-1/2 readings); nothing mutable at module
level.
"""
from price_model import WB_PriceModel  # noqa: F401  (dropped by build.py)

# Turn-1 market orders per family (verified with experiments/endgame/opening_check.py-style
# runs, both seats). TOP6 is detected so that it is NOT front-run.
WB_DP_OPENINGS = {
    "W3": [["BUY_PRODUCT", "WHEAT", 8], ["SELL", "WHEAT", 3], ["BUY_SEED", "WHEAT", 1]],
    "W0": [["BUY_PRODUCT", "WHEAT", 20], ["SELL", "WHEAT", 15], ["BUY_SEED", "WHEAT", 1]],
    "F2945": [["BUY_PRODUCT", "WHEAT", 20], ["SELL", "WHEAT", 15]],
    "TOP6": [["BUY_ANIMAL", "COW", 1], ["BUY_PRODUCT", "WHEAT", 5]],
}
WB_DP_TAPE_FAMILIES = ("W3", "W0", "F2945")
WB_DP_OUR_OPENING = WB_DP_OPENINGS["W3"]      # the splice plays W3's opening through step 191
WB_DP_SEED_COST = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}
WB_DP_ANIMAL_COST = {"GOOSE": 300, "COW": 400, "SHEEP": 500}
WB_DP_BUYABLE = ("WHEAT", "FERTILIZER")


def _wb_dp_fib(n):
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def _wb_dp_market(pm, orders_by_seat, inventory, money, sheds=None, hires=None,
                  shed_capacity=100, max_orders=10):
    """Exact port of kaggriculture._process_market for SELL / BUY_PRODUCT / BUY_SEED /
    BUY_ANIMAL / HIRE on copies of the state. Returns (inventory, money, sheds, hires)."""
    inv = dict(inventory)
    money = [float(m) for m in money]
    sheds = [dict(s) for s in (sheds or ({}, {}))]
    hires = list(hires or (0, 0))
    queues = [list(q or [])[:max_orders] for q in orders_by_seat]
    for i in range(max((len(q) for q in queues), default=0)):
        states = []
        for q in queues:
            o = q[i] if i < len(q) else None
            st = None
            if isinstance(o, list) and o:
                if o[0] in ("HIRE", "BUY_LAND"):
                    st = {"type": o[0]}
                elif o[0] in ("BUY_SEED", "BUY_PRODUCT", "BUY_ANIMAL", "SELL") and len(o) >= 3:
                    try:
                        n = int(o[2])
                    except (TypeError, ValueError):
                        n = 0
                    if n > 0:
                        st = {"type": o[0], "item": o[1], "remaining": n}
            states.append(st)
        for p, st in enumerate(states):               # atomic orders, in player order
            if st and st["type"] == "HIRE":
                cost = _wb_dp_fib(hires[p])
                if money[p] >= cost:
                    money[p] -= cost
                    hires[p] += 1
                states[p] = None
            elif st and st["type"] == "BUY_LAND":
                states[p] = None                      # not modelled (never in an opening)
        while True:
            quoted = [None, None]
            for p, st in enumerate(states):
                if st is None or st["remaining"] <= 0:
                    continue
                op, item = st["type"], st["item"]
                if op == "SELL" and item in inv:
                    quoted[p] = pm.quote(item, inv[item])
                elif op == "BUY_PRODUCT" and item in WB_DP_BUYABLE:
                    quoted[p] = pm.quote(item, inv[item] - 1)
                elif op == "BUY_SEED" and item in WB_DP_SEED_COST:
                    quoted[p] = WB_DP_SEED_COST[item]
                elif op == "BUY_ANIMAL" and item in WB_DP_ANIMAL_COST:
                    quoted[p] = WB_DP_ANIMAL_COST[item]
                else:
                    states[p] = None
            if all(q is None for q in quoted):
                break
            committed = False
            for p, price in enumerate(quoted):
                if price is None:
                    continue
                st = states[p]
                op, item = st["type"], st["item"]
                shed = sheds[p]
                ok = False
                if op == "SELL":
                    if shed.get(item, 0) > 0:
                        shed[item] -= 1
                        money[p] += price
                        if price > 1:
                            inv[item] += 1
                        ok = True
                elif op == "BUY_PRODUCT":
                    if money[p] >= price and sum(shed.values()) < shed_capacity:
                        money[p] -= price
                        shed[item] = shed.get(item, 0) + 1
                        inv[item] -= 1
                        ok = True
                elif op == "BUY_SEED":
                    if money[p] >= price:
                        money[p] -= price
                        ok = True
                elif op == "BUY_ANIMAL":
                    if money[p] >= price and sum(shed.values()) < shed_capacity:
                        money[p] -= price
                        shed[item] = shed.get(item, 0) + 1
                        ok = True
                if ok:
                    st["remaining"] -= 1
                    committed = True
                else:
                    states[p] = None
            if not committed:
                break
    return inv, money, sheds, hires


def WB_dp_signature(pm, family, our_seat, our_orders=None, starting_money=3000.0):
    """(opponent money, WHEAT market inventory) at obs step 1 if the opponent is `family`
    and we played `our_orders` on turn 1 from seat `our_seat`."""
    orders = [None, None]
    orders[our_seat] = our_orders if our_orders is not None else WB_DP_OUR_OPENING
    orders[1 - our_seat] = WB_DP_OPENINGS[family]
    inv = {p: pm.i0(p) for p in pm.params}
    inv, money, _, _ = _wb_dp_market(pm, orders, inv, [starting_money, starting_money])
    # The town centre takes 1 of every product (not FERTILIZER) at the end of the step-0 call.
    return money[1 - our_seat], inv["WHEAT"] - pm.drain_per_step("WHEAT", [], 0)


WB_DP_TAPE_T2 = [["HIRE"]] * 5 + [["BUY_ANIMAL", "COW", 2], ["BUY_ANIMAL", "SHEEP", 2]]
WB_DP_TOP6_T2 = [["SELL", "WHEAT", 1]] + [["HIRE"]] * 4 + [["BUY_ANIMAL", "COW", 1], ["BUY_ANIMAL", "SHEEP", 3]]
WB_DP_ROUTE_SWITCH = 144      # the shared router fixes the route from the first two shops here
WB_DP_ROUTE_ENDGAME = 648     # ...and switches every game to route 2 here
WB_DP_ENDGAME_ROUTE = 2


def WB_dp_signatures(pm, our_seat, our_t1=None, our_t2=None, starting_money=3000.0):
    """{family: ((opp money, WHEAT) at obs step 1, (opp money, WHEAT) at obs step 2)}."""
    out = {}
    for fam in WB_DP_OPENINGS:
        orders1 = [None, None]
        orders1[our_seat] = our_t1 if our_t1 is not None else WB_DP_OUR_OPENING
        orders1[1 - our_seat] = WB_DP_OPENINGS[fam]
        inv = {p: pm.i0(p) for p in pm.params}
        inv, money, sheds, hires = _wb_dp_market(pm, orders1, inv, [starting_money, starting_money])
        inv["WHEAT"] -= pm.drain_per_step("WHEAT", [], 0)
        s1 = (money[1 - our_seat], inv["WHEAT"])
        orders2 = [None, None]
        orders2[our_seat] = our_t2 if our_t2 is not None else WB_DP_TAPE_T2
        orders2[1 - our_seat] = WB_DP_TOP6_T2 if fam == "TOP6" else WB_DP_TAPE_T2
        inv, money, sheds, hires = _wb_dp_market(pm, orders2, inv, money, sheds, hires)
        out[fam] = (s1, (money[1 - our_seat], inv["WHEAT"]))
    return out


class WB_DumpPredictor:
    """Feed it every observation from step 0 (observe) - it needs steps 1 and 2 to detect.
    detect() then names the opponent family (or None); upcoming() lists its predicted dumps."""

    def __init__(self, price_model, our_t1=None, our_t2=None, dumps=None, key_route=None):
        self.pm = price_model
        self.our_t1, self.our_t2 = our_t1, our_t2
        self.dumps = dumps if dumps is not None else WB_DP_DUMPS
        self.key_route = key_route if key_route is not None else WB_DP_KEY_ROUTE
        self.family = None
        self.readings = {}           # obs step -> (opp money, WHEAT inventory, our money)
        self._sigs = None
        self.hits = 0                # audited predicted dumps that showed up in the market
        self.misses = 0              # ...that did not (a W3-opening non-tape, e.g. our own splice)
        self.disabled = False
        self._last = None            # (obs step, market inventory, shops) of the previous observe()

    # ---- detection ----------------------------------------------------------------
    def observe(self, obs):
        """Call on every turn from step 0. Detects at steps 1-2, then audits predictions."""
        step = int(obs["step"])
        if step in (1, 2) and step not in self.readings:
            me = int(obs["player"])
            farms = obs["farms"]
            self.readings[step] = (float(farms[1 - me]["money"]), int(obs["market"]["inventory"]["WHEAT"]),
                                   float(farms[me]["money"]))
            if self._sigs is None:
                self._sigs = WB_dp_signatures(self.pm, me, self.our_t1, self.our_t2)
            self.family = self._match()
        inv = obs["market"]["inventory"]
        if self._last is not None and self._last[0] == step - 1 and self.family in WB_DP_TAPE_FAMILIES:
            self._audit(step - 1, self._last[1], inv, self._last[2], obs)
        self._last = (step, dict(inv), list(obs["town"]["unlocked_shops"] or []))
        return self.active_family()

    def active_family(self):
        return None if self.disabled else self.family

    def _audit(self, t, inv_before, inv_after, shops, obs):
        """A predicted dump at call t must raise that market by at least half its size once
        the drain is added back (our own same-call sales only make a miss look like a hit)."""
        fam = self.dumps.get(self.family) or {}
        table = fam.get(self.keyed_route(obs)) if t >= WB_DP_ROUTE_SWITCH else None
        if table is None:
            table = fam.get("any") or {}
        for product, rows in table.items():
            for s, q in rows:
                if s == t:
                    delta = inv_after[product] - inv_before[product] + self.pm.drain_per_step(product, shops, t)
                    if delta >= max(1, q // 2):
                        self.hits += 1
                    else:
                        self.misses += 1
        if self.misses >= 2 and self.misses > self.hits:
            self.disabled = True

    def _match(self):
        """Every reading we have must equal the family's expected (money, WHEAT)."""
        hits = []
        for fam, sig in self._sigs.items():
            if all(self.readings[s][:2] == sig[s - 1] for s in self.readings):
                hits.append(fam)
        return hits[0] if len(hits) == 1 else None

    def detect(self, obs_or_history):
        """Family name ('W3', 'W0', 'F2945', 'TOP6') or None. Takes one observation or a
        list in step order; only observations of steps 1 and 2 identify the opponent."""
        seq = obs_or_history if isinstance(obs_or_history, (list, tuple)) else [obs_or_history]
        for o in seq:
            self.observe(o)
        return self.active_family()

    # ---- prediction ---------------------------------------------------------------
    def keyed_route(self, obs):
        """The route the opponent's router picks at step 144: first two shops, with the
        rival-key override (the tape reads its rival's money and WHEAT at step 2 - ours)."""
        shops = tuple((obs["town"]["unlocked_shops"] or [])[:2])
        if len(shops) < 2:
            return None
        route = self.key_route.get(shops)
        r2 = self.readings.get(2)
        if route is not None and "YARN_STORE" in shops and r2 is not None:
            route = WB_DP_RIVAL_ROUTE.get((round(r2[2], 3), r2[1]), route)
        return route

    def route(self, obs):
        """The route the opponent tape is replaying at this step."""
        step = int(obs["step"])
        if step >= WB_DP_ROUTE_ENDGAME:
            return WB_DP_ENDGAME_ROUTE
        if step < WB_DP_ROUTE_SWITCH:
            return 0
        return self.keyed_route(obs)

    def upcoming(self, obs, product, horizon_steps):
        """[(step, qty)] the opponent is predicted to SELL of `product` in the calls for obs
        steps step+1 .. step+horizon_steps (a sale in the current call cannot be beaten).
        The measured table is indexed by the keyed route (the route used from step 144)
        and covers the whole game, the day-27 switch to route 2 included."""
        if self.active_family() not in WB_DP_TAPE_FAMILIES:
            return []
        step = int(obs["step"])
        fam = self.dumps.get(self.family) or {}
        table = fam.get(self.keyed_route(obs)) if step >= WB_DP_ROUTE_SWITCH else None
        if table is None:
            table = fam.get("any") or {}
        return [(s, q) for s, q in table.get(product, ()) if step < s <= step + horizon_steps]


